:root {
  --ink: #17383a;
  --paper: #fffdf4;
  --signal: #d9ed58;
}

.cache-card {
  box-sizing: border-box;
  width: 460px;
  padding: 16px;
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 14px;
  color: var(--ink);
}

header {
  display: flex;
  align-items: center;
  gap: 12px;
}

.icon {
  display: grid;
  width: 46px;
  height: 46px;
  place-items: center;
  background: var(--signal);
  border-radius: 50%;
  font-size: 24px;
}

.eyebrow {
  margin: 0 0 3px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
}

h1 {
  margin: 0;
  font-size: 21px;
  line-height: 1.1;
}

footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 14px;
  padding-top: 10px;
  border-top: 1px solid var(--ink);
  font-size: 13px;
}

strong {
  padding: 4px 9px;
  background: var(--signal);
  border-radius: 999px;
  font-size: 11px;
  letter-spacing: 0.8px;
}
